import json,glob,os,sys
res={}
byid={}
for f in glob.glob('/tmp/export/*.ndjson'):
    t=os.path.basename(f)[:-7]
    res[t]=[json.loads(l) for l in open(f) if l.strip()]
    for r in res[t]: byid[r['id']]=r
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time') or ''
def subj(r):
    s=r.get('subject') or r.get('patient') or r.get('for')
    return s['reference'].split('/')[-1] if s else None

pats=json.load(open('/tmp/patients.json'))['patients']
spec_by_acc={}
for s in res['Specimen']: spec_by_acc.setdefault(s['accessionIdentifier']['value'],[]).append(s)
basic_by_acc={}
for b in res['Basic']: basic_by_acc.setdefault(ext(b,'accession'),[]).append(b)

target=sys.argv[1] if len(sys.argv)>1 else None
for p in pats:
    pid=p['patient']['id']
    if target and pid!=target: continue
    pt=p['patient']
    print('='*100)
    print(pid, pt['identifier'][0]['value'], pt['birthDate'], pt['gender'], pt['name'][0]['text'])
    for e in p['episodes']: print('  EPISODE',e['id'],e['period']['start'],e['status'])
    recs=[r for t in res for r in res[t] if subj(r)==pid and t not in('Patient','EpisodeOfCare')]
    recs.sort(key=et)
    for r in recs:
        t=r['resourceType']; rid=r['id']
        if t=='Observation':
            sp=byid.get((r.get('specimen') or {}).get('reference','').split('/')[-1])
            acc=(r.get('identifier') or [{}])[0].get('value')
            notes='; '.join(n['text'] for n in r.get('note',[]))
            print(f"  [{et(r)[:16]}] Obs {rid} {r['code']['text']} coll={r.get('effectiveDateTime','')[:16]} issued={r.get('issued','')[:16]} status={r['status']} val={r.get('valueString')!r} acc={acc} spec={sp['id'] if sp else None}")
            if notes: print(f"        note: {notes}")
            if sp:
                print(f"        SPEC {sp['id']} acc={sp['accessionIdentifier']['value']} coll={sp['collection'].get('collectedDateTime','')[:16]} by={sp['collection'].get('collector',{}).get('display')} label={ext(sp,'label-name')}/{ext(sp,'label-mrn')}/{ext(sp,'label-dob')} subj={subj(sp)}")
                for b in basic_by_acc.get(sp['accessionIdentifier']['value'],[]):
                    print(f"        ACC  {b['id']} acc={ext(b,'accession')} {ext(b,'patient-name')}/{ext(b,'patient-mrn')}/{ext(b,'patient-dob')} recv={ext(b,'received')}")
        elif t=='MedicationAdministration':
            print(f"  [{et(r)[:16]}] MedAdmin {rid} {r['medicationCodeableConcept']['text']} {r['dosage']['text']} eff={r.get('effectiveDateTime','')[:16]} status={r['status']} perf={[x['actor']['display'] for x in r.get('performer',[])]} note={'; '.join(n['text'] for n in r.get('note',[]))}")
        elif t=='MedicationDispense':
            print(f"  [{et(r)[:16]}] MedDisp {rid} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver','')[:16]} instr={[d['text'] for d in r.get('dosageInstruction',[])]} note={'; '.join(n['text'] for n in r.get('note',[]))}")
        elif t=='Condition':
            print(f"  [{et(r)[:16]}] Condition {rid} {r['code']['text']} recorded={r.get('recordedDate','')[:16]} by={r.get('recorder',{}).get('display')}")
        elif t=='DocumentReference':
            print(f"  [{et(r)[:16]}] Doc {rid} type={r['type']['text']} date={r.get('date','')[:16]} author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')}")
