            print(f"  [{et(r)[:16]}] Task {rid} {r.get('status')} {r.get('code',{}).get('coding',[{}])[0].get('code')} {r.get('description')}")
        elif t=='Specimen':
            pass
        else:
            print('  ',t,rid,json.dumps(r)[:300])
